#include "model_flex_lookup.h"
#include <fstream>
#include <iostream>
static uint32_t read(std::ifstream&in){uint32_t v;if(!in.read(reinterpret_cast<char*>(&v),4))throw std::runtime_error("short oracle");return v;}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("oracle required");std::ifstream in(argv[1],std::ios::binary);const char*names[]={"Alpha","Beta","Gamma"};const char*queries[]={"alpha","BETA","gamma","Missing"};for(unsigned scenario=0;scenario<6;++scenario)for(unsigned initial:{0u,8u,32u})for(unsigned q=0;q<4;++q){RecoveredGlobalFlexRegistryCandidate registry;for(unsigned i=0;i<21;++i)registry.registerName(i==7?"Alpha":i==20?"Beta":i==4?"Gamma":"seed_"+std::to_string(i));std::vector<MdlFlexControllerMetadata> records;for(unsigned i=0;i<3;++i)records.push_back({i,"",names[i],scenario==5?(i==0?7:i==1?20:4):-1,0,0x3f800000});std::vector<uint32_t> weights;for(unsigned i=0;i<initial;++i)weights.push_back(0x3f000000u+i);auto result=recoveredModelFlexLookupCandidate(scenario<3?nullptr:&records,queries[q],weights,scenario==3?nullptr:&registry);auto expected=read(in),count=read(in),calls=read(in);if(result!=expected||weights.size()!=count)throw std::runtime_error("lookup result mismatch");unsigned expectedCalls=scenario==4?std::min(q+1,3u):0;if(calls!=expectedCalls)throw std::runtime_error("native visit count mismatch");for(auto&r:records){uint32_t bits;std::memcpy(&bits,&r.diskGlobalIndex,4);if(bits!=read(in))throw std::runtime_error("controller mutation mismatch");}for(auto v:weights)if(v!=read(in))throw std::runtime_error("weight mismatch");}if(in.peek()!=EOF)throw std::runtime_error("trailing oracle");std::cout<<"x64 model flex lookup:72 native comparisons passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
